import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0012: Why Unauthorized High-risk Network Actions Are Forbidden","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0012-why-unauthorized-high-risk-network-actions-are-forbidden.md","filePath":"adr/ADR-0012-why-unauthorized-high-risk-network-actions-are-forbidden.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0012-why-unauthorized-high-risk-network-actions-are-forbidden.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0012-why-unauthorized-high-risk-network-actions-are-forbidden" tabindex="-1">ADR-0012: Why Unauthorized High-risk Network Actions Are Forbidden <a class="header-anchor" href="#adr-0012-why-unauthorized-high-risk-network-actions-are-forbidden" aria-label="Permalink to “ADR-0012: Why Unauthorized High-risk Network Actions Are Forbidden”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/security.md §12.2, platforms.md</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>A self-healing engine holds privileges to restart services, reset network interfaces, and change routes. Network actions differ fundamentally from ordinary service restarts: <strong>they can cut the management channel</strong> — Wi-Fi reconnect fails, the default route is cleared, the firewall is reset — the engine loses contact with the operator entirely, and this is exactly when the system most needs a human. A self-healing system losing its own connection is the worst failure mode.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>High-risk actions (<code>RiskLevel::High</code>: interface reset, system reboot, firewall clearing) are denied by default; they require explicit authorization (<code>permissions.default_allow_high_risk</code> or per-resource <code>recovery_policy.allow_high_risk</code>) and every execution enters the authorization audit; interface resets must be explicitly flagged &quot;may interrupt management channel&quot;; network operations have a global mutex (P3), with blanket firewall clears / full route resets forbidden.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Allow by default, audit after</strong>: once contact is lost, the audit is meaningless.</li><li><strong>Per-resource default allow</strong>: one configuration mistake exposes everything.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: the blast radius of destructive actions is explicitly controlled by configuration; the audit chain answers &quot;who authorized it, when it ran.&quot; Cons: capability requires configuration (documentation and examples must be clear); the &quot;worth enabling high-risk&quot; judgment falls on the user.</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>Every P2 platform adapter&#39;s dangerous primitive must have a permission check first (todo P2 §permission checks).</li><li>The P4 authorization UI shares the audit source, no custom permission model.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};